ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  contents: [
    {
      parts: [
        {
          text: "You are a marketing email specialist. Generate a professional customer retention email body for the following campaign.\n\nUse EXACTLY these placeholders:\n- {{CUSTOMER_NAME}} for the customer name\n- {{VALID_TILL}} for subscription expiry date\n- {{CHURN_SCORE}} for churn score\n- {{CAMPAIGN_NAME}} for the campaign name\n\nCampaign Details:\nName: " ++ (vars.inputPayload.campaign.Name default "Retention Campaign") ++ "\nDescription: " ++ (vars.inputPayload.campaign.Description default "Special retention offer for our valued customers") ++ "\n\nWrite only the email body (no subject line). Keep it under 200 words. Be warm, professional, and persuasive. End with a clear call-to-action."
        }
      ]
    }
  ]
}
